    min_r = min(r for r, _ in points)
    max_r = max(r for r, _ in points)
    min_c = min(col for _, col in points)
    max_c = max(col for _, col in points)
    mask = [(r - min_r, col - min_c) for r, col in points]
    mh, mw = max_r - min_r + 1, max_c - min_c + 1

    out = [row[:] for row in grid]
    for top in range(h - mh + 1):
