def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    foreground = min((c for c in counts if c != background), key=lambda c: counts[c])

    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] == foreground]
    r0 = min(r for r, c in points)
    c0 = min(c for r, c in points)
    shape = [(r - r0, c - c0) for r, c in points]

    out = [row[:] for row in grid]
    placements = []
    for top in range(h):
        for left in range(w):
            if all(0 <= top + dr < h and 0 <= left + dc < w
                   and grid[top + dr][left + dc] == 0
                   for dr, dc in shape):
                placements.append((top, left))

    for top, left in placements:
        for dr, dc in shape:
            out[top + dr][left + dc] = foreground
    return out
